  }
}

.card {
  padding: 2em;
}

.read-the-docs {
  color: #888;
}

import { Search, Layers, Zap } from 'lucide-react'

const steps = [
  {
    icon: Search,
    step: '01',
    title: 'PHASE 01 :: SCAN',
    description: (
      <>
        Executing deep traversal. <code className="font-mono text-emerald-400 bg-zinc-800 px-1.5 py-0.5 rounded text-sm">cmp</code> strips the noise (node_modules) and isolates the signal.
      </>
    ),
  },
  {
    icon: Layers,
    step: '02',
    title: 'PHASE 02 :: COMPRESS',
    description: 'Your file hierarchy is tokenized into a deterministic map. We preserve structure, not just text.',
  },
  {
    icon: Zap,
    step: '03',
    title: 'PHASE 03 :: INJECT',
    description: 'The payload is ready. One paste restores full Senior Engineer context instantly.',
  },
]

export default function HowItWorks() {
  return (
    <section id="protocol" className="py-20 px-4 sm:px-6 lg:px-8">
      <div className="max-w-6xl mx-auto">
        <div className="text-center mb-12">
          <h2 className="text-3xl sm:text-4xl font-bold font-mono text-zinc-100 mb-4">
            // THE PROTOCOL
          </h2>
          <p className="text-zinc-400 text-lg">
            Three phases. Zero friction. Total recall.
          </p>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {steps.map((step, index) => (
            <div key={index} className="relative">
              {index < steps.length - 1 && (
                <div className="hidden md:block absolute top-12 left-full w-full h-px bg-gradient-to-r from-zinc-700 to-transparent -translate-x-1/2 z-0" />
              )}
              <div className="relative z-10 text-center">
                <div className="w-24 h-24 mx-auto flex items-center justify-center bg-zinc-900 border-2 border-emerald-400/30 rounded-2xl mb-6">
                  <step.icon className="w-10 h-10 text-emerald-400" />
                </div>
                <div className="font-mono text-sm text-emerald-400 mb-2">
                  {step.step}
                </div>
                <h3 className="text-xl font-bold font-mono text-zinc-100 mb-3">
                  {step.title}
                </h3>
                <p className="text-zinc-400 leading-relaxed">
                  {step.description}
                </p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  )
}

import { Check, Terminal, RefreshCw, Package, Gift, Sparkles } from 'lucide-react'
import { useState, useEffect } from 'react'

const features = [
  { icon: Terminal, text: 'Rust Binary' },
  { icon: Package, text: 'CLI Tool' },
  { icon: RefreshCw, text: 'Free Updates' },
]

function CountdownTimer() {
  const [timeLeft, setTimeLeft] = useState<number | null>(null)
  const [expired, setExpired] = useState(false)

  useEffect(() => {
    const saved = localStorage.getItem('cmp-discount-timer')
    if (saved) {
      const remaining = parseInt(saved) - Date.now()
      if (remaining > 0) {
        setTimeLeft(remaining)
      } else {
        setExpired(true)
      }
    } else {
      const fourHours = 4 * 60 * 60 * 1000
      const expiresAt = Date.now() + fourHours
      localStorage.setItem('cmp-discount-timer', String(expiresAt))
      setTimeLeft(fourHours)
    }
  }, [])

  useEffect(() => {
    if (timeLeft === null || expired) return

    const interval = setInterval(() => {
      const saved = localStorage.getItem('cmp-discount-timer')
      if (saved) {
        const remaining = parseInt(saved) - Date.now()
        if (remaining > 0) {
          setTimeLeft(remaining)
        } else {
          setExpired(true)
          setTimeLeft(0)
        }
      }
    }, 1000)
    return () => clearInterval(interval)
  }, [timeLeft, expired])

  const hours = Math.floor((timeLeft || 0) / (1000 * 60 * 60))
  const minutes = Math.floor(((timeLeft || 0) % (1000 * 60 * 60)) / (1000 * 60))
  const seconds = Math.floor(((timeLeft || 0) % (1000 * 60)) / 1000)
  const pad = (n: number) => n.toString().padStart(2, '0')

  if (expired) {
    return (
      <div className="flex items-center justify-center gap-2 text-emerald-400">
        <Sparkles className="w-5 h-5" />
        <span className="font-medium">We've reserved your discount — claim it anytime.</span>
        <Sparkles className="w-5 h-5" />
      </div>
    )
  }

  if (timeLeft === null) return null

  return (
    <div className="flex items-center justify-center gap-2 font-mono text-lg">
      <div className="bg-zinc-800 px-3 py-2 rounded">{pad(hours)}</div>
      <span className="text-emerald-400">:</span>
      <div className="bg-zinc-800 px-3 py-2 rounded">{pad(minutes)}</div>
      <span className="text-emerald-400">:</span>
      <div className="bg-zinc-800 px-3 py-2 rounded">{pad(seconds)}</div>
    </div>
  )
}

export default function Pricing() {
  return (
    <section id="pricing" className="py-20 px-4 sm:px-6 lg:px-8">
      <div className="max-w-3xl mx-auto text-center">
        <h2 className="text-3xl sm:text-4xl font-bold text-zinc-100 mb-4">
          Stop fighting the context window.
        </h2>
        <p className="text-zinc-400 text-lg mb-12">
          One purchase. Lifetime access. No subscriptions.
        </p>
        <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-8 sm:p-12">
          {/* Christmas Discount Banner */}
          <div className="bg-emerald-400/10 border border-emerald-400/30 rounded-lg p-4 mb-8">
            <div className="flex items-center justify-center gap-2 text-emerald-400 mb-3">
              <Gift className="w-5 h-5" />
              <span className="font-mono font-semibold">🎄 CHRISTMAS SPECIAL — 70% OFF</span>
              <Gift className="w-5 h-5" />
            </div>
            <CountdownTimer />
          </div>

          {/* Pricing */}
          <div className="mb-8">
            <div className="flex items-baseline justify-center gap-3">
              <span className="text-2xl text-zinc-500 line-through">$99.00</span>
              <span className="text-5xl sm:text-6xl font-bold text-emerald-400">$29.70</span>
              <span className="text-zinc-500 text-lg">USD</span>
            </div>
            <div className="mt-2 text-sm text-emerald-400/80">
              You save $69.30 (70% off)
            </div>
          </div>

          <div className="flex flex-col sm:flex-row items-center justify-center gap-6 mb-8">
            {features.map((feature, index) => (
              <div key={index} className="flex items-center gap-2 text-zinc-300">
                <feature.icon className="w-5 h-5 text-emerald-400" />
                <span>{feature.text}</span>
              </div>
            ))}
          </div>
          <a
            href="https://www.paypal.com/ncp/payment/PENSKE7YSYK5A"
            target="_blank"
            rel="noopener noreferrer"
            className="inline-flex items-center gap-2 px-8 py-4 text-lg font-mono font-semibold text-zinc-950 bg-emerald-400 hover:bg-emerald-300 rounded-lg transition-colors glow"
          >
            <Check className="w-5 h-5" />
            Get Access Now
          </a>
          <p className="mt-6 text-sm text-zinc-500">
            Instant download. Works on macOS, Linux, and Windows.
          </p>
        </div>
      </div>
    </section>
  )
}

import { Clock, Copy, AlertTriangle } from 'lucide-react'

const problems = [
  {
    icon: Clock,
    title: 'Context Rot.',
    description: 'The model forgets your types.ts or directory structure after 15 minutes.',
    code: 'types.ts',
  },
  {
    icon: Copy,
    title: 'The Manual Grind.',
    description: 'You spend 20% of your coding time copy-pasting files just to remind the AI where things are.',
  },
  {
    icon: AlertTriangle,
    title: 'Hallucinations.',
    description: 'RAG guesses based on "vibes". It misses crucial dependencies. CMP maps them mathematically.',
  },
]

export default function Problem() {
  return (
    <section className="py-20 px-4 sm:px-6 lg:px-8 bg-zinc-900/50">
      <div className="max-w-6xl mx-auto">
        <div className="text-center mb-12">
          <h2 className="text-3xl sm:text-4xl font-bold text-zinc-100 mb-4">
            The Problem
          </h2>
          <p className="text-zinc-400 text-lg">
            Every AI coding session ends the same way.
          </p>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {problems.map((problem, index) => (
            <div
              key={index}
              className="p-6 bg-zinc-900 border border-zinc-800 rounded-lg hover:border-zinc-700 transition-colors"
            >
              <div className="w-12 h-12 flex items-center justify-center bg-red-500/10 rounded-lg mb-4">
                <problem.icon className="w-6 h-6 text-red-400" />
              </div>
              <h3 className="text-xl font-semibold text-zinc-100 mb-2">
                {problem.title}
              </h3>
              <p className="text-zinc-400 leading-relaxed">
                {problem.code ? (
                  <>
                    The model forgets your{' '}
                    <code className="font-mono text-emerald-400 bg-zinc-800 px-1.5 py-0.5 rounded text-sm">
                      {problem.code}
                    </code>{' '}
                    or directory structure after 15 minutes.
                  </>
                ) : (
                  problem.description
                )}
              </p>
            </div>
          ))}
        </div>
      </div>
    </section>
  )
}

@import "tailwindcss";

@theme {
  --font-mono: 'JetBrains Mono', 'Fira Code', 'SF Mono', Consolas, monospace;
  --color-accent: #10b981;
  --color-accent-hover: #34d399;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
}

.font-mono {
  font-family: var(--font-mono);
}

/* Terminal cursor blink */
@keyframes blink {
  0%, 50% { opacity: 1; }
  51%, 100% { opacity: 0; }
}

.cursor-blink {
  animation: blink 1s infinite;
}

/* Glow effect for accent elements */
.glow {
  box-shadow: 0 0 20px rgba(16, 185, 129, 0.3);
}

